SELECT t.*, u.user_name, u.avatar FROM industry_news_like t, tb_user u WHERE t.user_id = u.user_id
and t.news_id = #{industryNewsLike.newsId}
order by create_time desc

select count(*)
from industry_news n,
     industry_news_like l
where n.news_id = l.news_id
  and n.status = 1
  and l.user_id = #{userId}
